class Solution:
    def minOperationsQueries(self, n: int, edges: List[List[int]], queries: List[List[int]]) -> List[int]:
        g = [[] for _ in range(n)]
        for u, v, w in edges:
            g[u].append((v, w))
            g[v].append((u, w))
        parent = [[(-1, 0)] for _ in range(n)]
        order, seen = [], [False] * n
        stack = [0]; seen[0] = True
        while stack:
            u = stack.pop(); order.append(u)
            for v, w in g[u]:
                if not seen[v]:
                    seen[v] = True
                    parent[v][0] = (u, w)
                    stack.append(v)
        depth = [0] * n
        for u in order[1:]:
            depth[u] = depth[parent[u][0][0]] + 1
        res = []
        for a, b in queries:
            ca, cb = [], []
            x, y = a, b
            while depth[x] > depth[y]:
                ca.append(parent[x][0][1]); x = parent[x][0][0]
            while depth[y] > depth[x]:
                cb.append(parent[y][0][1]); y = parent[y][0][0]
            while x != y:
                ca.append(parent[x][0][1]); x = parent[x][0][0]
                cb.append(parent[y][0][1]); y = parent[y][0][0]
            cnt = [0] * 27
            for w in ca + cb: cnt[w] += 1
            res.append(len(ca) + len(cb) - max(cnt))
        return res

