class Solution {
public:
    vector<int> minOperationsQueries(int n, vector<vector<int>>& edges, vector<vector<int>>& queries) {
        vector<vector<pair<int,int>>> g(n);
        for (auto& e : edges) {
            g[e[0]].push_back({e[1], e[2]});
            g[e[1]].push_back({e[0], e[2]});
        }
        vector<pair<int,int>> par(n, {-1, 0});
        vector<int> depth(n, 0), order;
        vector<bool> seen(n, false);
        stack<int> st; st.push(0); seen[0] = true;
        while (!st.empty()) {
            int u = st.top(); st.pop(); order.push_back(u);
            for (auto [v, w] : g[u]) if (!seen[v]) {
                seen[v] = true; par[v] = {u, w}; st.push(v);
            }
        }
        for (size_t i = 1; i < order.size(); i++)
            depth[order[i]] = depth[par[order[i]].first] + 1;
        vector<int> res;
        for (auto& q : queries) {
            int x = q[0], y = q[1];
            vector<int> ws;
            while (depth[x] > depth[y]) { ws.push_back(par[x].second); x = par[x].first; }
            while (depth[y] > depth[x]) { ws.push_back(par[y].second); y = par[y].first; }
            while (x != y) {
                ws.push_back(par[x].second); x = par[x].first;
                ws.push_back(par[y].second); y = par[y].first;
            }
            int cnt[27] = {0};
            for (int w : ws) cnt[w]++;
            res.push_back((int)ws.size() - *max_element(cnt, cnt + 27));
        }
        return res;
    }
};

