class Solution {
    public int[] minOperationsQueries(int n, int[][] edges, int[][] queries) {
        List<int[]>[] g = new List[n];
        for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
        for (int[] e : edges) {
            g[e[0]].add(new int[]{e[1], e[2]});
            g[e[1]].add(new int[]{e[0], e[2]});
        }
        int[][] par = new int[n][2];
        for (int[] p : par) p[0] = -1;
        int[] depth = new int[n];
        boolean[] seen = new boolean[n];
        Deque<Integer> st = new ArrayDeque<>();
        st.push(0); seen[0] = true;
        List<Integer> order = new ArrayList<>();
        while (!st.isEmpty()) {
            int u = st.pop(); order.add(u);
            for (int[] nb : g[u]) if (!seen[nb[0]]) {
                seen[nb[0]] = true; par[nb[0]][0] = u; par[nb[0]][1] = nb[1]; st.push(nb[0]);
            }
        }
        for (int i = 1; i < order.size(); i++)
            depth[order.get(i)] = depth[par[order.get(i)][0]] + 1;
        int[] res = new int[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            int x = queries[qi][0], y = queries[qi][1];
            int[] cnt = new int[27];
            int total = 0;
            while (depth[x] > depth[y]) { cnt[par[x][1]]++; total++; x = par[x][0]; }
            while (depth[y] > depth[x]) { cnt[par[y][1]]++; total++; y = par[y][0]; }
            while (x != y) {
                cnt[par[x][1]]++; total++; x = par[x][0];
                cnt[par[y][1]]++; total++; y = par[y][0];
            }
            int mx = 0;
            for (int w = 1; w <= 26; w++) mx = Math.max(mx, cnt[w]);
            res[qi] = total - mx;
        }
        return res;
    }
}

