class Solution:
    def minOperationsQueries(self, n: int, edges: List[List[int]], queries: List[List[int]]) -> List[int]:
        LOG = 14
        g = [[] for _ in range(n)]
        for u, v, w in edges:
            g[u].append((v, w - 1)); g[v].append((u, w - 1))
        depth = [0] * n
        par = [[0] * LOG for _ in range(n)]
        cnt = [[[0] * 26 for _ in range(LOG)] for _ in range(n)]
        from collections import deque
        dq = deque([0]); vis = [False] * n; vis[0] = True
        while dq:
            u = dq.popleft()
            for v, w in g[u]:
                if not vis[v]:
                    vis[v] = True; depth[v] = depth[u] + 1; par[v][0] = u
                    cnt[v][0] = cnt[u][0][:]; cnt[v][0][w] += 1
                    dq.append(v)
        for k in range(1, LOG):
            for v in range(n):
                par[v][k] = par[par[v][k-1]][k-1]
                cu, cp = cnt[v][k-1], cnt[par[v][k-1]][k-1]
                cnt[v][k] = [cu[i] + cp[i] for i in range(26)]
        def query(a, b):
            acc = [0] * 26
            if depth[a] < depth[b]: a, b = b, a
            d = depth[a] - depth[b]
            for k in range(LOG):
                if (d >> k) & 1:
                    for i in range(26): acc[i] += cnt[a][k][i]
                    a = par[a][k]
            if a == b:
                return sum(acc) - max(acc)
            for k in range(LOG - 1, -1, -1):
                if par[a][k] != par[b][k]:
                    for i in range(26):
                        acc[i] += cnt[a][k][i] + cnt[b][k][i]
                    a, b = par[a][k], par[b][k]
            for i in range(26): acc[i] += cnt[a][0][i] + cnt[b][0][i]
            return sum(acc) - max(acc)
        return [query(a, b) for a, b in queries]

