class Solution {
public:
    vector<int> minOperationsQueries(int n, vector<vector<int>>& edges, vector<vector<int>>& queries) {
        const int LOG = 14;
        vector<vector<pair<int,int>>> g(n);
        for (auto& e : edges) {
            g[e[0]].push_back({e[1], e[2] - 1});
            g[e[1]].push_back({e[0], e[2] - 1});
        }
        vector<array<int,LOG>> par(n);
        vector<array<array<int,26>,LOG>> cnt(n);
        vector<int> depth(n, 0);
        for (auto& p : par) p.fill(0);
        for (auto& c : cnt) for (auto& row : c) row.fill(0);
        queue<int> q; vector<bool> vis(n, false);
        q.push(0); vis[0] = true;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto [v, w] : g[u]) if (!vis[v]) {
                vis[v] = true; depth[v] = depth[u] + 1; par[v][0] = u;
                cnt[v][0] = cnt[u][0]; cnt[v][0][w]++;
                q.push(v);
            }
        }
        for (int k = 1; k < LOG; k++)
            for (int v = 0; v < n; v++) {
                par[v][k] = par[par[v][k-1]][k-1];
                for (int i = 0; i < 26; i++)
                    cnt[v][k][i] = cnt[v][k-1][i] + cnt[par[v][k-1]][k-1][i];
            }
        vector<int> res;
        res.reserve(queries.size());
        for (auto& qr : queries) {
            int a = qr[0], b = qr[1];
            array<int,26> acc{};
            if (depth[a] < depth[b]) swap(a, b);
            int d = depth[a] - depth[b];
            for (int k = 0; k < LOG; k++) if ((d >> k) & 1) {
                for (int i = 0; i < 26; i++) acc[i] += cnt[a][k][i];
                a = par[a][k];
            }
            if (a != b) {
                for (int k = LOG - 1; k >= 0; k--) if (par[a][k] != par[b][k]) {
                    for (int i = 0; i < 26; i++) acc[i] += cnt[a][k][i] + cnt[b][k][i];
                    a = par[a][k]; b = par[b][k];
                }
                for (int i = 0; i < 26; i++) acc[i] += cnt[a][0][i] + cnt[b][0][i];
            }
            int tot = 0, mx = 0;
            for (int i = 0; i < 26; i++) { tot += acc[i]; mx = max(mx, acc[i]); }
            res.push_back(tot - mx);
        }
        return res;
    }
};

