class Solution {
    static final int LOG = 14;
    public int[] minOperationsQueries(int n, int[][] edges, int[][] queries) {
        List<int[]>[] g = new List[n];
        for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
        for (int[] e : edges) {
            g[e[0]].add(new int[]{e[1], e[2] - 1});
            g[e[1]].add(new int[]{e[0], e[2] - 1});
        }
        int[][] par = new int[n][LOG];
        int[][][] cnt = new int[n][LOG][26];
        int[] depth = new int[n];
        boolean[] vis = new boolean[n];
        Deque<Integer> dq = new ArrayDeque<>();
        dq.add(0); vis[0] = true;
        while (!dq.isEmpty()) {
            int u = dq.poll();
            for (int[] nb : g[u]) if (!vis[nb[0]]) {
                int v = nb[0], w = nb[1];
                vis[v] = true; depth[v] = depth[u] + 1; par[v][0] = u;
                System.arraycopy(cnt[u][0], 0, cnt[v][0], 0, 26);
                cnt[v][0][w]++;
                dq.add(v);
            }
        }
        for (int k = 1; k < LOG; k++)
            for (int v = 0; v < n; v++) {
                par[v][k] = par[par[v][k-1]][k-1];
                for (int i = 0; i < 26; i++)
                    cnt[v][k][i] = cnt[v][k-1][i] + cnt[par[v][k-1]][k-1][i];
            }
        int[] res = new int[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            int a = queries[qi][0], b = queries[qi][1];
            int[] acc = new int[26];
            if (depth[a] < depth[b]) { int t = a; a = b; b = t; }
            int d = depth[a] - depth[b];
            for (int k = 0; k < LOG; k++) if (((d >> k) & 1) == 1) {
                for (int i = 0; i < 26; i++) acc[i] += cnt[a][k][i];
                a = par[a][k];
            }
            if (a != b) {
                for (int k = LOG - 1; k >= 0; k--) if (par[a][k] != par[b][k]) {
                    for (int i = 0; i < 26; i++) acc[i] += cnt[a][k][i] + cnt[b][k][i];
                    a = par[a][k]; b = par[b][k];
                }
                for (int i = 0; i < 26; i++) acc[i] += cnt[a][0][i] + cnt[b][0][i];
            }
            int tot = 0, mx = 0;
            for (int i = 0; i < 26; i++) { tot += acc[i]; mx = Math.max(mx, acc[i]); }
            res[qi] = tot - mx;
        }
        return res;
    }
}

